    /// <remarks>URL names: <c>skip_processing</c>, <c>skp</c>, <c>sp</c>; arguments <c>ext…</c>; default —. Milestone M1; scope request.</remarks>
    public sealed record SkipProcessing : ProcessingOption
    {
        /// <summary>Serve sources of these formats unprocessed.</summary>
        /// <remarks>URL names: <c>skip_processing</c>, <c>skp</c>, <c>sp</c>; arguments <c>ext…</c>; default —. Milestone M1; scope request.</remarks>
        /// <param name="format">source format served as is. One of <c>jpeg</c>, <c>jpg</c>, <c>png</c>, <c>webp</c>, <c>avif</c>, <c>jxl</c>, <c>heic</c>, <c>gif</c>, <c>tiff</c>, <c>bmp</c>, <c>ico</c>, <c>svg</c>, <c>mp4</c>, <c>webm</c>, <c>hevc</c>, <c>h265</c>.</param>
        /// <param name="formats">Repeated argument: format — source format served as is. One of <c>jpeg</c>, <c>jpg</c>, <c>png</c>, <c>webp</c>, <c>avif</c>, <c>jxl</c>, <c>heic</c>, <c>gif</c>, <c>tiff</c>, <c>bmp</c>, <c>ico</c>, <c>svg</c>, <c>mp4</c>, <c>webm</c>, <c>hevc</c>, <c>h265</c>.</param>
        public SkipProcessing(string format, params string[] formats)
            : base("skip_processing", Args0(format, formats))
        {
        }

        private static OptionArg[] Args0(string format, string[] formats)
        {
            ArgumentNullException.ThrowIfNull(formats);
            var args = new List<OptionArg>(1 + (formats.Length * 1)) { format };
            foreach (var e in formats)
            {
                args.Add(e);
            }

            return [.. args];
        }
    }

