    /// <remarks>URL names: <c>zoom</c>, <c>z</c>; arguments <c>x[:y]</c>; default 1. Milestone M1; scope pipeline.</remarks>
    public sealed record Zoom : ProcessingOption
    {
        /// <summary>Zoom factor applied after resizing.</summary>
        /// <remarks>URL names: <c>zoom</c>, <c>z</c>; arguments <c>x[:y]</c>; default 1. Milestone M1; scope pipeline.</remarks>
        /// <param name="x">horizontal zoom factor. Range &gt; 0.</param>
        /// <param name="y">vertical zoom factor (default: x). Range &gt; 0.</param>
        public Zoom(double x, double? y = null)
            : base("zoom", OptionArgs.Trim([x, y], 1))
        {
        }
    }
}
